def cover(row_no, keys, why=None):
    coverage.append({'manualRow': row_no, 'coveredBy': keys if isinstance(keys, list) else [keys], 'note': why})
def skip(row_no, why): skipped.append({'manualRow': row_no, 'reason': why})
